static bool load_obcp(const Harness_ObcpDef *def)
{
   asn1SccOBCP_Code code;
   const size_t len = strlen(def->src) + 1;

   if (len > sizeof(code.arr)) {
      harness_report_failure_and_exit("Could not load OBCP %.5s: source size %zu exceeds limit %zu\n",
                                      def->id,
                                      len,
                                      sizeof(code.arr));
      return false;
   }

   memcpy(code.arr, def->src, len);
   code.nCount = (int)len;

   asn1SccT_Boolean ok = FALSE;
   harness_RI_load_obcp(&def->id, &code, &ok);
   if (!ok) {
      harness_report_failure_and_exit("Could not load OBCP %.5s\n", def->id);
   }
   return (bool)ok;
}

