static void make_load_limit_test_id(unsigned index, asn1SccOBCP_Id id)
{
   id[0] = 'L';
   id[1] = 'M';
   id[2] = 'T';
   id[3] = (char)('0' + ((index / 10u) % 10u));
   id[4] = (char)('0' + (index % 10u));
}

static bool can_load_obcp_id(const asn1SccOBCP_Id *id)
{
   asn1SccT_Boolean ok = FALSE;

   harness_RI_can_obcp_be_loaded(id, &ok);
   return (bool)ok;
}

static bool try_load_obcp_id(const asn1SccOBCP_Id *id, const char *src)
{
   asn1SccOBCP_Code code;
   const size_t len = strlen(src) + 1u;
   asn1SccT_Boolean ok = FALSE;

   if (len > sizeof(code.arr)) {
      harness_error_printf("Load limit test FAILED: probe source size %zu exceeds limit %zu\n",
                           len,
                           sizeof(code.arr));
      return false;
   }

   memcpy(code.arr, src, len);
   code.nCount = (int)len;
   harness_RI_load_obcp(id, &code, &ok);

   return (bool)ok;
}

static bool try_unload_obcp_id(const asn1SccOBCP_Id *id)
{
   asn1SccT_Boolean ok = FALSE;

   harness_RI_unload_obcp(id, &ok);
   return (bool)ok;
}

static bool run_load_limit_test(void)
{
   static const char load_limit_test_src[] = "pass\n";
   asn1SccOBCP_Id loaded_ids[LOAD_LIMIT_TEST_MAX_OBCPS];
   unsigned loaded_count = 0u;
   bool limit_reached = false;
   bool extra_load_rejected = false;
   bool cleanup_ok = true;

   for (unsigned index = 0u; index < LOAD_LIMIT_TEST_MAX_OBCPS; ++index) {
      asn1SccOBCP_Id id;

      make_load_limit_test_id(index, id);
      if (!can_load_obcp_id(&id)) {
         limit_reached = true;
         break;
      }
      if (!try_load_obcp_id(&id, load_limit_test_src)) {
         harness_error_printf("Load limit test FAILED: could not load probe OBCP %.5s before limit was reached\n",
                              id);
         cleanup_ok = false;
         break;
      }

      memcpy(loaded_ids[loaded_count], id, sizeof(asn1SccOBCP_Id));
      loaded_count++;
   }

   if (limit_reached) {
      asn1SccOBCP_Id extra_id;

      make_load_limit_test_id(loaded_count, extra_id);
      extra_load_rejected = !can_load_obcp_id(&extra_id) &&
                            !try_load_obcp_id(&extra_id, load_limit_test_src);
   }

   for (unsigned index = 0u; index < loaded_count; ++index) {
      if (!try_unload_obcp_id(&loaded_ids[index])) {
         harness_error_printf("Load limit test FAILED: could not unload probe OBCP %.5s during cleanup\n",
                              loaded_ids[index]);
         cleanup_ok = false;
      }
   }

   if (!limit_reached) {
      harness_error_printf("Load limit test FAILED: no load limit reached within %u probe OBCPs\n",
                           LOAD_LIMIT_TEST_MAX_OBCPS);
   }

   if (limit_reached && !extra_load_rejected) {
      harness_error_printf("Load limit test FAILED: engine accepted an extra load beyond the discovered limit\n");
   }

   // Main makefile should declare OBCP_MAXIMUM_NUMBER_OF_LOADED_OBCPS as 12
   // 12 is hardcoded to verify that the declaration in the Makefile is the source of truth.
   if (loaded_count != 12)
   {
      harness_error_printf("Loaded OBCP count (%u) does not match the one configured in Makefile\n",
                           loaded_count);
   }

   if (limit_reached && extra_load_rejected && cleanup_ok && loaded_count == 12u) {
      printf("Load limit test PASSED: load limit reached after %u probe OBCPs and one extra load was rejected\n",
             loaded_count);
      return true;
   }

   return false;
}

/* -----------------------------------------------------------------------
 * Test result table
 * ----------------------------------------------------------------------- */

typedef enum {
   TEST_NOT_RUN = 0,
   TEST_PASS,
   TEST_FAIL
} Harness_TestStatus;

typedef struct {
   const char        *name;
   Harness_TestStatus status;
} Harness_TestResult;

typedef enum {
   T_IO_WRITE        = 0,
   T_DATAPOOL,
   T_EVENTS,
   T_STEP_CONTROL,
   T_CONCURRENCY,
   T_GETTIME,
   T_PKT_ENV_RECV,
   T_PKT_INTER_OBCP,
   T_PKT_NONBLOCKING,
   T_PKT_CANSEND,
   T_PKT_ENV_SEND,
   T_ABORT,
   T_STOP,
   T_PRECOMPILED,
   T_LOAD_LIMIT,
   T_COUNT
} Harness_TestIndex;

static Harness_TestResult test_results[T_COUNT] = {
   [T_IO_WRITE]        = { "IO write output",                          TEST_NOT_RUN },
   [T_DATAPOOL]        = { "Datapool read/write (int/enum/float/bool)", TEST_NOT_RUN },
   [T_EVENTS]          = { "Events sequence",                          TEST_NOT_RUN },
   [T_STEP_CONTROL]    = { "Step control (beginstep/endstep)",         TEST_NOT_RUN },
   [T_CONCURRENCY]     = { "Concurrent OBCP execution",                TEST_NOT_RUN },
   [T_GETTIME]         = { "Gettime accuracy",                         TEST_NOT_RUN },
   [T_PKT_ENV_RECV]    = { "Packet: Env->OBCP receive (timed)",        TEST_NOT_RUN },
   [T_PKT_INTER_OBCP]  = { "Packet: OBCP-to-OBCP exchange",           TEST_NOT_RUN },
   [T_PKT_NONBLOCKING] = { "Packet: non-blocking + availability",      TEST_NOT_RUN },
   [T_PKT_CANSEND]     = { "Packet: cansendpacket",                    TEST_NOT_RUN },
   [T_PKT_ENV_SEND]    = { "Packet: OBCP->Env send",                   TEST_NOT_RUN },
   [T_ABORT]           = { "Abort OBCP (terminates infinite loop)",    TEST_NOT_RUN },
   [T_STOP]            = { "Stop OBCP at endstep boundary",            TEST_NOT_RUN },
   [T_PRECOMPILED]     = { "Precompiled OBCP bytecode",                TEST_NOT_RUN },
   [T_LOAD_LIMIT]      = { "Loaded OBCP limit",                        TEST_NOT_RUN },
};

static void test_record(Harness_TestIndex idx, bool passed)
{
   test_results[idx].status = passed ? TEST_PASS : TEST_FAIL;
}

static void report_final_results(void)
{
   static const char * const status_str[] = { "NOT RUN", "PASS   ", "FAIL   " };
   bool all_pass = true;
   printf("\n========================================\n");
   printf(" Test Results\n");
   printf("========================================\n");
   for (int i = 0; i < T_COUNT; i++) {
      const Harness_TestStatus s = test_results[i].status;
      if (s != TEST_PASS) { all_pass = false; }
      printf("  [%s] %s\n", status_str[s], test_results[i].name);
   }
   printf("----------------------------------------\n");
   printf("  Overall: %s\n", all_pass ? "PASS" : "FAIL");
   printf("========================================\n");
}

/* -----------------------------------------------------------------------
 * Trigger state machine
 * ----------------------------------------------------------------------- */

typedef enum {
   PHASE_INIT,
   PHASE_IO_WRITE_TEST,
   PHASE_DATAPOOL_TEST,
   PHASE_EVENTS_TEST,
   PHASE_STEP_TEST_WAIT_STEP4,
   PHASE_STEP_TEST_COMPLETE,
   PHASE_CONCURRENCY_WAIT_TEST1,
   PHASE_CONCURRENCY_ALL_RUNNING,
   PHASE_GETTIME_TEST,
   PHASE_PACKETS_INIT,
   PHASE_PACKETS_RUNNING,
   PHASE_ABORT_TEST_RUNNING,
   PHASE_ABORT_TEST_WAIT,
   PHASE_STOP_TEST_RUNNING,
   PHASE_STOP_TEST_WAIT,
   PHASE_PRECOMPILED_TEST,
} Harness_Phase;

static Harness_Phase harness_phase = PHASE_INIT;
static Harness_Phase harness_phase_timeout_phase = PHASE_INIT;
static uint64_t      harness_phase_started_ns = 0ULL;

#define HARNESS_PHASE_TIMEOUT_NS 20000000000ULL

static Harness_Phase harness_get_phase(void)
{
   return harness_phase;
}

static void harness_set_phase(Harness_Phase phase)
{
   harness_phase = phase;
}

static bool harness_phase_has_timeout(Harness_Phase phase)
{
   return phase != PHASE_INIT;
}

static void harness_record_phase_timeout(Harness_Phase phase)
{
   switch (phase) {
      case PHASE_IO_WRITE_TEST:
         test_record(T_IO_WRITE, false);
         break;
      case PHASE_DATAPOOL_TEST:
         test_record(T_DATAPOOL, false);
         break;
      case PHASE_EVENTS_TEST:
         test_record(T_EVENTS, false);
         break;
      case PHASE_STEP_TEST_WAIT_STEP4:
      case PHASE_STEP_TEST_COMPLETE:
         test_record(T_STEP_CONTROL, false);
         break;
      case PHASE_CONCURRENCY_WAIT_TEST1:
      case PHASE_CONCURRENCY_ALL_RUNNING:
         test_record(T_CONCURRENCY, false);
         break;
      case PHASE_GETTIME_TEST:
         test_record(T_GETTIME, false);
         break;
      case PHASE_PACKETS_INIT:
      case PHASE_PACKETS_RUNNING:
         test_record(T_PKT_ENV_RECV, false);
         test_record(T_PKT_INTER_OBCP, false);
         test_record(T_PKT_NONBLOCKING, false);
         test_record(T_PKT_CANSEND, false);
         test_record(T_PKT_ENV_SEND, false);
         break;
      case PHASE_ABORT_TEST_RUNNING:
      case PHASE_ABORT_TEST_WAIT:
         test_record(T_ABORT, false);
         break;
      case PHASE_STOP_TEST_RUNNING:
      case PHASE_STOP_TEST_WAIT:
         test_record(T_STOP, false);
         break;
      case PHASE_PRECOMPILED_TEST:
         test_record(T_PRECOMPILED, false);
         break;
      default:
         break;
   }
}

/* This function is not broken down on purpose, as the tests execute
   phase by phase, semi-asynchronously.
   Each test is usually broken down the following way:
   - state N -> initialization,
   - state N+1 -> verification.
   As a consequence, in state N+1:
   - test N is being verified,
   - test N + 1 is being started.
   Partial verification is sometimes done in provided interfaces 
   (e.g., event or write counting).
   In such case, trigger verifies the partial results.
   */
void harness_PI_trigger(void)
{
   const Harness_Phase phase = harness_get_phase();
   const uint64_t now_ns = Hal_GetElapsedTimeInNs();

   if (phase != harness_phase_timeout_phase) {
      harness_phase_timeout_phase = phase;
      harness_phase_started_ns = now_ns;
   } else if (harness_phase_has_timeout(phase) &&
              now_ns - harness_phase_started_ns >= HARNESS_PHASE_TIMEOUT_NS) {
      harness_record_phase_timeout(phase);
      harness_report_failure_and_exit("Harness FAILED: phase %d timed out after %llu ns\n",
                                      (int)phase,
                                      (unsigned long long)(now_ns - harness_phase_started_ns));
      return;
   }

   switch (phase) {

      /* -----------------------------------------------------------------
       * Start the engine and kick off the IO write test OBCP.
       * ----------------------------------------------------------------- */
      case PHASE_INIT: {
         harness_RI_start_obcp_engine();

         harness_lock_state();
         io_write_test_active = true;
         io_test_msg_index = 0;
         io_write_test_all_ok = true;
         harness_unlock_state();

         if (!load_obcp(&OBCP_IOTEST)) return;
         if (!activate_obcp(&OBCP_IOTEST)) return;

         printf("IO write test OBCP activated\n");
         harness_set_phase(PHASE_IO_WRITE_TEST);
         break;
      }

      /* -----------------------------------------------------------------
       * Wait for the IO write test OBCP to complete, then kick off the
       * datapool test OBCP.
       * ----------------------------------------------------------------- */
      case PHASE_IO_WRITE_TEST: {
         const asn1SccOBCP_Execution_Status sio = get_status(&OBCP_IOTEST);

         if (sio == OBCP_Execution_Status_inactive) {
            size_t io_test_count;
            bool io_test_ok;

            harness_lock_state();
            io_write_test_active = false;
            io_test_count = io_test_msg_index;
            io_test_ok = io_write_test_all_ok;
            harness_unlock_state();

            io_test_ok = io_test_ok && (io_test_count == IO_TEST_EXPECTED_COUNT);
            test_record(T_IO_WRITE, io_test_ok);
            if (io_test_count != IO_TEST_EXPECTED_COUNT) {
               harness_error_printf("IO test ERROR: expected %zu messages, received %zu\n",
                                    IO_TEST_EXPECTED_COUNT, io_test_count);
            } else if (io_test_ok) {
               printf("IO write tests finished — all %zu messages verified OK\n",
                      IO_TEST_EXPECTED_COUNT);
            }
            unload_obcp(&OBCP_IOTEST);

            {
               const asn1SccOBCP_Parameter_Id success_id = DPTEST_SUCCESS_PARAM_ID;
               asn1SccOBCP_Parameter_Value zero_val;
               zero_val.kind        = OBCP_Parameter_Value_int_value_PRESENT;
               zero_val.u.int_value = 0;
               harness_PI_set_parameter_value(&success_id, &zero_val);
            }

            if (!load_obcp(&OBCP_DPTEST)) return;
            if (!activate_obcp(&OBCP_DPTEST)) return;

            printf("Datapool test OBCP activated\n");
            harness_set_phase(PHASE_DATAPOOL_TEST);
         }
         break;
      }

      /* -----------------------------------------------------------------
       * Wait for the datapool test OBCP to complete, then launch the
       * concurrency tests (TEST1 and TEST2 run in parallel).
       * ----------------------------------------------------------------- */
      case PHASE_DATAPOOL_TEST: {
         const asn1SccOBCP_Execution_Status sdp = get_status(&OBCP_DPTEST);

         if (sdp == OBCP_Execution_Status_inactive) {
            const asn1SccOBCP_Parameter_Id success_id = DPTEST_SUCCESS_PARAM_ID;
            const asn1SccOBCP_Parameter_Type int_type = OBCP_Parameter_Type_integer_type;
            asn1SccOBCP_Parameter_Value success_val;

            harness_PI_get_parameter_value(&success_id, &int_type, &success_val);

            const bool datapool_ok =
               success_val.kind == OBCP_Parameter_Value_int_value_PRESENT &&
               success_val.u.int_value == 1;

            test_record(T_DATAPOOL, datapool_ok);
            if (datapool_ok) {
               printf("Datapool tests finished\n");
            } else {
               harness_error_printf("Datapool test FAILED: success flag param %u value=%d\n",
                                    (unsigned)success_id,
                                    success_val.kind == OBCP_Parameter_Value_int_value_PRESENT ?
                                       (int)success_val.u.int_value : -1);
            }
            unload_obcp(&OBCP_DPTEST);

            if (!load_obcp(&OBCP_EVTEST)) return;
            harness_lock_state();
            events_test_active         = true;
            events_test_received_count = 0;
            events_test_all_ok         = true;
            harness_unlock_state();
            if (!activate_obcp(&OBCP_EVTEST)) return;

            printf("Events test OBCP activated\n");
            harness_set_phase(PHASE_EVENTS_TEST);
         }
         break;
      }

      /* -----------------------------------------------------------------
       * Wait for the events test OBCP to complete, then verify that all
       * expected events were received, and launch the concurrency tests.
       * ----------------------------------------------------------------- */
      case PHASE_EVENTS_TEST: {
         const asn1SccOBCP_Execution_Status sev = get_status(&OBCP_EVTEST);

         if (sev == OBCP_Execution_Status_inactive) {
            bool events_ok_order;
            size_t events_count;

            harness_lock_state();
            events_test_active = false;
            events_ok_order = events_test_all_ok;
            events_count = events_test_received_count;
            harness_unlock_state();

            const bool events_ok = events_ok_order &&
                                   events_count == EVENTS_TEST_EXPECTED_COUNT;
            test_record(T_EVENTS, events_ok);
            if (!events_ok) {
               harness_error_printf("Events test FAILED: expected %zu events, received %zu%s\n",
                                    EVENTS_TEST_EXPECTED_COUNT,
                                    events_count,
                                    events_ok_order ? "" : " (order/ID mismatch)");
            } else {
               printf("Events test PASSED: all %zu events received in correct order\n",
                      EVENTS_TEST_EXPECTED_COUNT);
            }
            unload_obcp(&OBCP_EVTEST);

            /* Initialise step test datapool entries to zero before loading */
            {
               const asn1SccOBCP_Parameter_Id unblock_id = STEPTEST_UNBLOCK_PARAM_ID;
               const asn1SccOBCP_Parameter_Id reached_id = STEPTEST_REACHED_STEP_PARAM_ID;
               const asn1SccOBCP_Parameter_Id done_id    = STEPTEST_DONE_PARAM_ID;
               asn1SccOBCP_Parameter_Value zero_val;
               zero_val.kind        = OBCP_Parameter_Value_int_value_PRESENT;
               zero_val.u.int_value = 0;
               harness_PI_set_parameter_value(&unblock_id, &zero_val);
               harness_PI_set_parameter_value(&reached_id, &zero_val);
               harness_PI_set_parameter_value(&done_id,    &zero_val);
            }

            if (!load_obcp(&OBCP_STEPTEST)) return;
            if (!activate_obcp(&OBCP_STEPTEST)) return;

            printf("Step test OBCP activated\n");
            harness_set_phase(PHASE_STEP_TEST_WAIT_STEP4);
         }
         break;
      }

      /* -----------------------------------------------------------------
       * Poll until the OBCP reports that step 4 has begun, confirm it,
       * then unblock the OBCP by setting the unblock datapool parameter.
       * ----------------------------------------------------------------- */
      case PHASE_STEP_TEST_WAIT_STEP4: {
         const asn1SccOBCP_Step_Id current_step = get_current_step(&OBCP_STEPTEST);

         if (current_step == STEPTEST_BLOCKING_STEP) {
            printf("Step test: get_obcp_status reports step %u active — unblocking OBCP\n",
                   (unsigned)current_step);
            const asn1SccOBCP_Parameter_Id unblock_id = STEPTEST_UNBLOCK_PARAM_ID;
            asn1SccOBCP_Parameter_Value one_val;
            one_val.kind        = OBCP_Parameter_Value_int_value_PRESENT;
            one_val.u.int_value = 1;
            harness_PI_set_parameter_value(&unblock_id, &one_val);
            harness_set_phase(PHASE_STEP_TEST_COMPLETE);
         }
         break;
      }

      /* -----------------------------------------------------------------
       * Wait for the step test OBCP to finish, then verify that all
       * steps were executed and launch the concurrency tests.
       * ----------------------------------------------------------------- */
      case PHASE_STEP_TEST_COMPLETE: {
         const asn1SccOBCP_Execution_Status ss = get_status(&OBCP_STEPTEST);

         if (ss == OBCP_Execution_Status_inactive) {
            const asn1SccOBCP_Parameter_Type int_type  = OBCP_Parameter_Type_integer_type;
            asn1SccOBCP_Parameter_Value v;
            const asn1SccOBCP_Parameter_Id reached_id = STEPTEST_REACHED_STEP_PARAM_ID;
            const asn1SccOBCP_Parameter_Id done_id    = STEPTEST_DONE_PARAM_ID;

            harness_PI_get_parameter_value(&reached_id, &int_type, &v);
            const int32_t last_step = v.u.int_value;
            harness_PI_get_parameter_value(&done_id, &int_type, &v);
            const bool steps_done = (v.u.int_value == 1);

            const bool step_ok = steps_done && last_step == STEPTEST_LAST_STEP;
            test_record(T_STEP_CONTROL, step_ok);
            if (step_ok) {
               printf("Step test PASSED: all %d steps completed, "
                      "step %d hold-and-release verified\n",
                      STEPTEST_LAST_STEP, STEPTEST_BLOCKING_STEP);
            } else {
               harness_error_printf("Step test FAILED: steps_done=%d, last_step=%d "
                                    "(expected %d)\n",
                                    (int)steps_done, (int)last_step, STEPTEST_LAST_STEP);
            }

            unload_obcp(&OBCP_STEPTEST);

            if (!load_obcp(&OBCP_TEST1)) return;
            if (!load_obcp(&OBCP_TEST2)) return;
            if (!load_obcp(&OBCP_TEST3)) return;

            concurrency_test12_overlap_seen = false;
            concurrency_test23_overlap_seen = false;

            /* TEST1 and TEST2 start immediately; TEST3 waits for TEST1 */
            if (!activate_obcp(&OBCP_TEST1)) return;
            if (!activate_obcp(&OBCP_TEST2)) return;

            printf("TEST1 (3 s) and TEST2 (5 s) activated\n");
            harness_set_phase(PHASE_CONCURRENCY_WAIT_TEST1);
         }
         break;
      }

      /* -----------------------------------------------------------------
       * Wait for TEST1 to complete, then activate TEST3 to exercise
       * concurrent execution of two active OBCPs.
       * ----------------------------------------------------------------- */
      case PHASE_CONCURRENCY_WAIT_TEST1: {
         const asn1SccOBCP_Execution_Status s1 = get_status(&OBCP_TEST1);
         const asn1SccOBCP_Execution_Status s2 = get_status(&OBCP_TEST2);

         printf("Status — TEST1: %d  TEST2: %d\n",
                s1, s2);

         if (s1 == OBCP_Execution_Status_active_and_running &&
             s2 == OBCP_Execution_Status_active_and_running) {
            concurrency_test12_overlap_seen = true;
         }

         if (s1 == OBCP_Execution_Status_inactive) {
            printf("TEST1 finished — activating TEST3 (3 s)\n");
            unload_obcp(&OBCP_TEST1);
            if (!activate_obcp(&OBCP_TEST3)) return;
            harness_set_phase(PHASE_CONCURRENCY_ALL_RUNNING);
         }
         break;
      }

      /* -----------------------------------------------------------------
       * Wait for both remaining OBCPs to finish, then kick off the
       * gettime accuracy test.
       * ----------------------------------------------------------------- */
      case PHASE_CONCURRENCY_ALL_RUNNING: {
         const asn1SccOBCP_Execution_Status s2 = get_status(&OBCP_TEST2);
         const asn1SccOBCP_Execution_Status s3 = get_status(&OBCP_TEST3);

         printf("Status — TEST2: %d  TEST3: %d\n", s2, s3);

         if (s2 == OBCP_Execution_Status_active_and_running &&
             s3 == OBCP_Execution_Status_active_and_running) {
            concurrency_test23_overlap_seen = true;
         }

         if (s2 == OBCP_Execution_Status_inactive &&
             s3 == OBCP_Execution_Status_inactive)
         {
            const bool concurrency_ok = concurrency_test12_overlap_seen &&
                                        concurrency_test23_overlap_seen;

            test_record(T_CONCURRENCY, concurrency_ok);
            if (concurrency_ok) {
               printf("Concurrency test PASSED: TEST1/TEST2 and TEST2/TEST3 overlapped in active execution\n");
            } else {
               harness_error_printf("Concurrency test FAILED: overlap observed TEST1/TEST2=%d, TEST2/TEST3=%d\n",
                                    (int)concurrency_test12_overlap_seen,
                                    (int)concurrency_test23_overlap_seen);
            }
            unload_obcp(&OBCP_TEST2);
            unload_obcp(&OBCP_TEST3);

            if (!load_obcp(&OBCP_TIMETEST)) return;
            if (!activate_obcp(&OBCP_TIMETEST)) return;

            printf("Gettime test OBCP activated (waiting %d ms)\n",
                   TIMETEST_WAIT_MS);
            harness_set_phase(PHASE_GETTIME_TEST);
         }
         break;
      }

      /* -----------------------------------------------------------------
       * Wait for the gettime test OBCP to complete, then read the
       * elapsed time and pass/fail flag from the datapool and report.
       * ----------------------------------------------------------------- */
      case PHASE_GETTIME_TEST: {
         const asn1SccOBCP_Execution_Status st = get_status(&OBCP_TIMETEST);

         if (st == OBCP_Execution_Status_inactive) {
            /* Read results written by the OBCP into the datapool */
            const asn1SccOBCP_Parameter_Id elapsed_id = TIMETEST_ELAPSED_PARAM_ID;
            const asn1SccOBCP_Parameter_Id passed_id  = TIMETEST_PASSED_PARAM_ID;
            const asn1SccOBCP_Parameter_Type int_type  = OBCP_Parameter_Type_integer_type;
            asn1SccOBCP_Parameter_Value elapsed_val, passed_val;

            harness_PI_get_parameter_value(&elapsed_id, &int_type, &elapsed_val);
            harness_PI_get_parameter_value(&passed_id,  &int_type, &passed_val);

            const int32_t elapsed_ms = elapsed_val.u.int_value;
            const int32_t passed     = passed_val.u.int_value;

            test_record(T_GETTIME, passed != 0);
            if (passed) {
               printf("Gettime test PASSED: elapsed=%d ms "
                      "(nominal=%d ms, tolerance=\u00b1%d ms)\n",
                      elapsed_ms, TIMETEST_WAIT_MS, TIMETEST_TOLERANCE_MS);
            } else {
               harness_error_printf("Gettime test FAILED: elapsed=%d ms "
                                    "(expected %d\u00b1%d ms)\n",
                                    elapsed_ms, TIMETEST_WAIT_MS, TIMETEST_TOLERANCE_MS);
            }

            printf("Gettime test finished\n");
            unload_obcp(&OBCP_TIMETEST);
            harness_set_phase(PHASE_PACKETS_INIT);
         }
         break;
      }

      /* -----------------------------------------------------------------
       * Pre-inject the env-input packet on channel 0, then activate
       * OBCP_PKTRECV and OBCP_PKTSEND concurrently.
       * ----------------------------------------------------------------- */
      case PHASE_PACKETS_INIT: {
         /* Inject a 4-byte packet from the environment into channel 0.
          * OBCP_PKTRECV will pick it up with a timed receivepacket(). */
         const asn1SccOBCP_Channel_Id ch0 = PKTTEST_ENV_INPUT_CHANNEL;
         asn1SccOBCP_Packet env_in;
         memset(&env_in, 0, sizeof(env_in));
         env_in.arr[0] = (byte)0xAA;
         env_in.arr[1] = (byte)0xBB;
         env_in.arr[2] = (byte)0xCC;
         env_in.arr[3] = (byte)0xDD;
         env_in.nCount = 4;
         asn1SccT_Boolean receive_success = FALSE;
         const uint64_t deadline_ns = Hal_GetElapsedTimeInNs() + HARNESS_PACKET_RETRY_TIMEOUT_NS;
         while (!receive_success)
         {
            harness_RI_receive_packet(&ch0, &env_in, &receive_success);
            if (!receive_success) {
               if (Hal_GetElapsedTimeInNs() >= deadline_ns) {
                  harness_record_phase_timeout(PHASE_PACKETS_INIT);
                  harness_report_failure_and_exit("Packets test FAILED: timed out injecting env-input packet on channel 0\n");
                  return;
               }
               (void)Hal_SleepNs(HARNESS_PACKET_RETRY_SLEEP_NS);
            }
         }
         printf("Packets test: injected 4-byte env-input packet on channel 0\n");

         harness_lock_state();
         pkttest_active              = true;
         pkttest_env_output_received = false;
         harness_unlock_state();

         if (!load_obcp(&OBCP_PKTRECV)) return;
         if (!load_obcp(&OBCP_PKTSEND)) return;
         if (!activate_obcp(&OBCP_PKTRECV)) return;
         if (!activate_obcp(&OBCP_PKTSEND)) return;

         printf("Packets test OBCPs activated (PKTRECV + PKTSEND running concurrently)\n");
         harness_set_phase(PHASE_PACKETS_RUNNING);
         break;
      }

      /* -----------------------------------------------------------------
       * Wait for both packet OBCPs to complete, then read datapool results
       * and verify all aspects of the packets test.
       * ----------------------------------------------------------------- */
      case PHASE_PACKETS_RUNNING: {
         const asn1SccOBCP_Execution_Status sr = get_status(&OBCP_PKTRECV);
         const asn1SccOBCP_Execution_Status ss = get_status(&OBCP_PKTSEND);

         if (sr == OBCP_Execution_Status_inactive &&
             ss == OBCP_Execution_Status_inactive)
         {
            bool env_output_received;
            asn1SccOBCP_Packet env_output_packet;

            harness_lock_state();
            pkttest_active = false;
            env_output_received = pkttest_env_output_received;
            env_output_packet = pkttest_env_output_packet;
            harness_unlock_state();

            /* Read all four in-OBCP test outcomes from the datapool */
            const asn1SccOBCP_Parameter_Type int_type = OBCP_Parameter_Type_integer_type;
            asn1SccOBCP_Parameter_Value v;
            const asn1SccOBCP_Parameter_Id env_recv_id  = PKTTEST_ENV_RECEIVE_PARAM_ID;
            const asn1SccOBCP_Parameter_Id inter_id     = PKTTEST_INTER_OBCP_PARAM_ID;
            const asn1SccOBCP_Parameter_Id nonblock_id  = PKTTEST_NONBLOCKING_PARAM_ID;
            const asn1SccOBCP_Parameter_Id cansend_id   = PKTTEST_CANSEND_PARAM_ID;

            harness_PI_get_parameter_value(&env_recv_id,  &int_type, &v);
            const bool env_recv_ok  = (v.u.int_value == 1);
            harness_PI_get_parameter_value(&inter_id,     &int_type, &v);
            const bool inter_ok     = (v.u.int_value == 1);
            harness_PI_get_parameter_value(&nonblock_id,  &int_type, &v);
            const bool nonblock_ok  = (v.u.int_value == 1);
            harness_PI_get_parameter_value(&cansend_id,   &int_type, &v);
            const bool cansend_ok   = (v.u.int_value == 1);

            /* Verify the 16-byte packet sent from OBCP_PKTSEND to environment */
            bool env_out_ok = env_output_received &&
                              (env_output_packet.nCount == 16);
            if (env_out_ok) {
               for (int i = 0; i < 16; i++) {
                  if ((unsigned char)env_output_packet.arr[i] !=
                      pkttest_expected_env_output[i]) {
                     env_out_ok = false;
                     break;
                  }
               }
            }

            test_record(T_PKT_ENV_RECV,    env_recv_ok);
            test_record(T_PKT_INTER_OBCP,  inter_ok);
            test_record(T_PKT_NONBLOCKING, nonblock_ok);
            test_record(T_PKT_CANSEND,     cansend_ok);
            test_record(T_PKT_ENV_SEND,    env_out_ok);
            printf("Packets test results:\n");
            printf("  Env\u2192OBCP receive  (ch0, 4 B, 500 ms timeout): %s\n",
                   env_recv_ok ? "PASSED" : "FAILED");
            printf("  OBCP-to-OBCP exchange (ch0\u21921, 8 B, blocking):  %s\n",
                   inter_ok    ? "PASSED" : "FAILED");
            printf("  Non-blocking + availability checks (ch3):      %s\n",
                   nonblock_ok ? "PASSED" : "FAILED");
            printf("  cansendpacket (valid ch2 / invalid ch99):       %s\n",
                   cansend_ok  ? "PASSED" : "FAILED");
            printf("  OBCP\u2192Env send      (ch2, 16 B):                %s\n",
                   env_out_ok  ? "PASSED" : "FAILED");

            const bool all_ok = env_recv_ok && inter_ok && nonblock_ok &&
                                cansend_ok  && env_out_ok;
            printf("Packets test overall: %s\n", all_ok ? "PASSED" : "FAILED");
            if (!all_ok) {
               harness_error_printf("Packets test FAILED: one or more packet checks failed\n");
            }
            unload_obcp(&OBCP_PKTRECV);
            unload_obcp(&OBCP_PKTSEND);

            if (!load_obcp(&OBCP_ABORTTEST)) return;
            if (!activate_obcp(&OBCP_ABORTTEST)) return;
            printf("Abort test OBCP activated (infinite loop)\n");
            harness_set_phase(PHASE_ABORT_TEST_RUNNING);
         }
         break;
      }

      /* -----------------------------------------------------------------
       * Poll until the OBCP is actively running, then send abort.
       * ----------------------------------------------------------------- */
      case PHASE_ABORT_TEST_RUNNING: {
         const asn1SccOBCP_Execution_Status sa = get_status(&OBCP_ABORTTEST);
         if (sa == OBCP_Execution_Status_active_and_running) {
            printf("Abort test: OBCP is active_and_running \u2014 sending abort\n");
            abort_obcp(&OBCP_ABORTTEST);
            abort_test_wait_ticks = 0u;
            harness_set_phase(PHASE_ABORT_TEST_WAIT);
         }
         break;
      }

      /* -----------------------------------------------------------------
       * Wait for the aborted OBCP to reach inactive, then launch the
       * stop test.
       * ----------------------------------------------------------------- */
      case PHASE_ABORT_TEST_WAIT: {
         bool start_next_test = false;
         const asn1SccOBCP_Execution_Status sa = get_status(&OBCP_ABORTTEST);
         if (sa == OBCP_Execution_Status_inactive) {
            test_record(T_ABORT, true);
            printf("Abort test PASSED: OBCP transitioned to inactive after abort\n");
            unload_obcp(&OBCP_ABORTTEST);
            start_next_test = true;
         } else {
            abort_test_wait_ticks++;
            if (abort_test_wait_ticks >= ABORTTEST_WAIT_TIMEOUT_TICKS) {
               test_record(T_ABORT, false);
               harness_error_printf("Abort test FAILED: OBCP did not reach inactive within %u trigger ticks after abort request\n",
                                    ABORTTEST_WAIT_TIMEOUT_TICKS);
               // Abort does not work, so unloading makes no sense. We should have enough remaining slots.
               start_next_test = true;
            }
         }
         if (start_next_test)
         {
            /* Initialise stop test datapool entries to zero */
            {
               asn1SccOBCP_Parameter_Value zero_val;
               zero_val.kind        = OBCP_Parameter_Value_int_value_PRESENT;
               zero_val.u.int_value = 0;
               asn1SccOBCP_Parameter_Id pid;
               for (pid = STOPTEST_STEP1_PARAM_ID;
                    pid <= STOPTEST_DONE_PARAM_ID; ++pid) {
                  harness_PI_set_parameter_value(&pid, &zero_val);
               }
               const asn1SccOBCP_Parameter_Id unblock_id = STOPTEST_UNBLOCK_PARAM_ID;
               harness_PI_set_parameter_value(&unblock_id, &zero_val);
            }

            if (!load_obcp(&OBCP_STOPTEST)) return;
            if (!activate_obcp(&OBCP_STOPTEST)) return;
            printf("Stop test OBCP activated\n");
            harness_set_phase(PHASE_STOP_TEST_RUNNING);
         }
         break;
      }

      /* -----------------------------------------------------------------
       * Wait until the OBCP is blocked in step 2; request stop at step 3
       * then unblock so it advances to step 3 and the stop fires there.
       * ----------------------------------------------------------------- */
      case PHASE_STOP_TEST_RUNNING: {
         const asn1SccOBCP_Step_Id current_step = get_current_step(&OBCP_STOPTEST);
         if (current_step == STOPTEST_BLOCKING_STEP) {
            printf("Stop test: OBCP is in step %u \u2014 requesting stop at step %u\n",
                   (unsigned)current_step, (unsigned)STOPTEST_TARGET_STEP);
            stop_obcp_at(&OBCP_STOPTEST, STOPTEST_TARGET_STEP);
            const asn1SccOBCP_Parameter_Id unblock_id = STOPTEST_UNBLOCK_PARAM_ID;
            asn1SccOBCP_Parameter_Value one_val;
            one_val.kind        = OBCP_Parameter_Value_int_value_PRESENT;
            one_val.u.int_value = 1;
            harness_PI_set_parameter_value(&unblock_id, &one_val);
            harness_set_phase(PHASE_STOP_TEST_WAIT);
         }
         break;
      }

      /* -----------------------------------------------------------------
       * Wait for the stopped OBCP to reach inactive, then verify that
       * steps 1-3 ran (params 40-42 == 1) and steps 4-5 did not
       * (params 43-45 == 0).
       * ----------------------------------------------------------------- */
      case PHASE_STOP_TEST_WAIT: {
         const asn1SccOBCP_Execution_Status ss = get_status(&OBCP_STOPTEST);
         if (ss == OBCP_Execution_Status_inactive) {
            const asn1SccOBCP_Parameter_Type int_type = OBCP_Parameter_Type_integer_type;
            asn1SccOBCP_Parameter_Value v;
            bool ok = true;
            asn1SccOBCP_Parameter_Id pid;

            /* Steps 1-3 body must have run (params 40-42 == 1) */
            for (pid = STOPTEST_STEP1_PARAM_ID;
                 pid <= STOPTEST_STEP3_PARAM_ID; ++pid) {
               harness_PI_get_parameter_value(&pid, &int_type, &v);
               if (v.u.int_value != 1) {
                  harness_error_printf("Stop test FAILED: param %u expected 1, got %d "
                                       "(step body before/at stop not executed)\n",
                                       (unsigned)pid, (int)v.u.int_value);
                  ok = false;
               }
            }

            /* Steps 4-5 and done flag must NOT have run (params 43-45 == 0) */
            for (pid = STOPTEST_STEP4_PARAM_ID;
                 pid <= STOPTEST_DONE_PARAM_ID; ++pid) {
               harness_PI_get_parameter_value(&pid, &int_type, &v);
               if (v.u.int_value != 0) {
                  harness_error_printf("Stop test FAILED: param %u expected 0, got %d "
                                       "(execution continued past stop step)\n",
                                       (unsigned)pid, (int)v.u.int_value);
                  ok = false;
               }
            }

            test_record(T_STOP, ok);
            if (ok) {
               printf("Stop test PASSED: OBCP stopped at endstep(%d); "
                      "steps 1-%d body executed, steps %d+ not reached\n",
                      STOPTEST_TARGET_STEP, STOPTEST_TARGET_STEP,
                      STOPTEST_TARGET_STEP + 1);
            }
            unload_obcp(&OBCP_STOPTEST);

            {
               const asn1SccOBCP_Parameter_Id precompiled_param_id = 42u;
               asn1SccOBCP_Parameter_Value zero_val;
               zero_val.kind        = OBCP_Parameter_Value_int_value_PRESENT;
               zero_val.u.int_value = 0;
               harness_PI_set_parameter_value(&precompiled_param_id, &zero_val);
            }

            if (!load_precompiled_obcp(&OBCP_PRECOMPILED_TEST)) return;
            if (!activate_precompiled_obcp(&OBCP_PRECOMPILED_TEST)) return;
            printf("Precompiled OBCP test activated\n");
            harness_set_phase(PHASE_PRECOMPILED_TEST);
         }
         break;
      }

      /* -----------------------------------------------------------------
       * Wait for the precompiled OBCP to finish, then verify that it wrote
       * datapool parameter 42 with value 1234 before running the load-limit
       * test and reporting final results.
       * ----------------------------------------------------------------- */
      case PHASE_PRECOMPILED_TEST: {
         const asn1SccOBCP_Execution_Status sp = get_precompiled_status(&OBCP_PRECOMPILED_TEST);

         if (sp == OBCP_Execution_Status_inactive) {
            const asn1SccOBCP_Parameter_Id precompiled_param_id = 42u;
            const asn1SccOBCP_Parameter_Type int_type = OBCP_Parameter_Type_integer_type;
            asn1SccOBCP_Parameter_Value value;

            harness_PI_get_parameter_value(&precompiled_param_id, &int_type, &value);

            const bool precompiled_ok =
               value.kind == OBCP_Parameter_Value_int_value_PRESENT &&
               value.u.int_value == 1234;

            test_record(T_PRECOMPILED, precompiled_ok);
            if (precompiled_ok) {
               printf("Precompiled OBCP test PASSED: parameter %u updated to %d\n",
                      (unsigned)precompiled_param_id,
                      (int)value.u.int_value);
            } else {
               harness_error_printf("Precompiled OBCP test FAILED: parameter %u expected 1234, got %d\n",
                                    (unsigned)precompiled_param_id,
                                    value.kind == OBCP_Parameter_Value_int_value_PRESENT ?
                                       (int)value.u.int_value : -1);
            }

            unload_precompiled_obcp(&OBCP_PRECOMPILED_TEST);
            test_record(T_LOAD_LIMIT, run_load_limit_test());
            report_final_results();
            printf("All tests finished — exiting\n");
            kill(getpid(), SIGTERM);
         }
         break;
      }

      default:
         harness_report_failure_and_exit("Harness ERROR: unexpected phase %d\n", (int)phase);
         return;
   }
}


